-- earnings-sync cron jobs (pg_cron). Same net.http_post + anon-key pattern as the
-- existing mover-scan / news-poll jobs. Two UTC variants per slot because ET shifts
-- on Nov 1 (DST); the function's ET gate runs only the variant that lands in-window.
-- Weekdays only (1-5). Re-runnable: cron.schedule upserts by jobname.

-- morning  07:00 ET  (11:00 UTC EDT / 12:00 UTC EST)
select cron.schedule('earnings-sync-morning-a', '0 11 * * 1-5',
  $$SELECT net.http_post(url := 'https://siwrhqcojoyxxwaxnopc.supabase.co/functions/v1/earnings-sync', headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InNpd3JocWNvam95eHh3YXhub3BjIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzg2MjEwMDUsImV4cCI6MjA5NDE5NzAwNX0._Dp0woo3iIcCCN5yQGgIGbBHZW8evf5MLUqIaudVlaU','apikey','eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InNpd3JocWNvam95eHh3YXhub3BjIiwicm9sZSI6ImFub24iLCJpYXQiOjE3Nzg2MjEwMDUsImV4cCI6MjA5NDE5NzAwNX0._Dp0woo3iIcCCN5yQGgIGbBHZW8evf5MLUqIaudVlaU'), body := '{"slot":"morning"}'::jsonb, timeout_milliseconds := 30000);$$);
